insert into journal_posts (slug, status, title, excerpt, cover, category, blocks, author, reading_minutes, publish_at)
values ('how-a-sardine-is-made', 'published', '{"en":"How a sardine is made: from clay to glaze","pt":"Como nasce uma sardinha: do barro ao vidrado"}'::jsonb, '{"en":"Two firings, five days and a very steady hand. A morning in the studio with our painters.","pt":"Duas cozeduras, cinco dias e uma mão muito firme. Uma manhã no atelier com as nossas pintoras."}'::jsonb, '/journal/studio.svg', '{"en":"Behind the scenes","pt":"Nos bastidores"}'::jsonb, '[{"type":"p","text":{"en":"Every sardine starts as a slab of fine white stoneware, pressed by hand into a plaster mould we carved ourselves. It dries for two days before its first firing at 980°C, which turns it into bisque: pale, porous and ready for colour.","pt":"Cada sardinha começa como uma placa de grés branco fino, prensada à mão num molde de gesso que nós próprios esculpimos. Seca durante dois dias antes da primeira cozedura a 980°C, que a transforma em chacota: pálida, porosa e pronta para a cor."}},{"type":"h2","text":{"en":"Painting, one brushstroke at a time","pt":"Pintar, uma pincelada de cada vez"}},{"type":"p","text":{"en":"Our painters work freehand. Scales, stripes and azulejo flowers are never traced, so no two fish are the same. A single Statement sardine can take a whole afternoon.","pt":"As nossas pintoras trabalham à mão livre. Escamas, riscas e flores de azulejo nunca são decalcadas, por isso não há dois peixes iguais. Uma sardinha Statement pode levar uma tarde inteira."}},{"type":"image","src":"/journal/painting.svg","alt":{"en":"Hands painting blue scales on a ceramic sardine","pt":"Mãos a pintar escamas azuis numa sardinha de cerâmica"},"caption":{"en":"Cobalt scales, painted freehand.","pt":"Escamas em cobalto, pintadas à mão livre."}},{"type":"quote","text":{"en":"If two sardines look identical, one of us wasn''t paying attention.","pt":"Se duas sardinhas forem iguais, alguém estava distraído."}},{"type":"h2","text":{"en":"The second firing","pt":"A segunda cozedura"}},{"type":"p","text":{"en":"A clear, lead-free glaze goes on last. At 1,200°C it melts into glass and gives the colours the wet, glossy look people notice first. It''s also why we can''t promise the exact shade you see on screen: the kiln decides the details.","pt":"Por fim, um vidrado transparente sem chumbo. A 1.200°C derrete em vidro e dá às cores aquele brilho molhado que salta à vista. É também por isso que não prometemos o tom exato do ecrã: os pormenores são do forno."}},{"type":"products","slugs":["sardine-wall-decor","sardine-set-of-5","sardine-ornament"]}]'::jsonb, 'Terra Collective', 5, '2026-09-15')
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, cover = excluded.cover, category = excluded.category, blocks = excluded.blocks, reading_minutes = excluded.reading_minutes;

insert into journal_posts (slug, status, title, excerpt, cover, category, blocks, author, reading_minutes, publish_at)
values ('petiscos-table-guide', 'published', '{"en":"Setting a petiscos table, the Portuguese way","pt":"Como pôr uma mesa de petiscos"}'::jsonb, '{"en":"Olives, good bread, a bottle of oil and small plates for sharing. Our guide to a slow Portuguese evening.","pt":"Azeitonas, pão bom, um fio de azeite e pratinhos para partilhar. O nosso guia para um serão sem pressa."}'::jsonb, '/journal/table.svg', '{"en":"At the table","pt":"À mesa"}'::jsonb, '[{"type":"p","text":{"en":"Petiscos are Portugal''s small plates: a little of everything, eaten slowly with friends. The only rules are to keep portions small and to keep the wine coming.","pt":"Os petiscos são os pratinhos de Portugal: um pouco de tudo, comido devagar com amigos. As únicas regras: porções pequenas e vinho sempre a correr."}},{"type":"h2","text":{"en":"Start with olives and oil","pt":"Comece com azeitonas e azeite"}},{"type":"p","text":{"en":"Put out a dish of garlicky olives, a bowl of tremoços and a good bottle of Alentejo olive oil for the bread. Serve the oil in a bottle you''d be happy to leave on the table.","pt":"Um prato de azeitonas com alho, uma taça de tremoços e uma boa garrafa de azeite alentejano para o pão. Sirva o azeite numa garrafa que tenha gosto em deixar na mesa."}},{"type":"products","slugs":["olive-appetizer-dishes","ceramic-oil-bottle","olive-oil-dispenser"]},{"type":"h2","text":{"en":"Then the tins","pt":"Depois, as latas"}},{"type":"p","text":{"en":"Open a few tins of good conservas and serve them straight from the tin with lemon, parsley and toast.","pt":"Abra umas boas latas de conservas e sirva-as na própria lata, com limão, salsa e tostas."}}]'::jsonb, 'Terra Collective', 4, '2026-08-30')
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, cover = excluded.cover, category = excluded.category, blocks = excluded.blocks, reading_minutes = excluded.reading_minutes;

insert into journal_posts (slug, status, title, excerpt, cover, category, blocks, author, reading_minutes, publish_at)
values ('gift-guide-under-50', 'published', '{"en":"The Terra gift guide: joyful things under €50","pt":"Guia de presentes Terra: alegrias até 50 €"}'::jsonb, '{"en":"Easy to wrap, easy to post, and very Portuguese. Our favourite small gifts this season.","pt":"Fáceis de embrulhar, fáceis de enviar e muito portugueses. Os nossos presentes pequenos favoritos."}'::jsonb, '/journal/gifts.svg', '{"en":"Gift guides","pt":"Guias de presentes"}'::jsonb, '[{"type":"p","text":{"en":"Everything below ships in our gift box, and you can add a handwritten note at checkout for €4.","pt":"Tudo o que está abaixo segue na nossa caixa de oferta, e pode juntar uma mensagem escrita à mão no checkout por 4 €."}},{"type":"products","slugs":["tinned-fish-playing-cards","yellow-trinket-box","sardine-ornament","azulejo-coaster-set"]},{"type":"h2","text":{"en":"For the cook","pt":"Para quem cozinha"}},{"type":"p","text":{"en":"A sardine spoon rest and an oil bottle make a lovely pair. Tie them together with kitchen string.","pt":"Um descanso de colher sardinha e uma garrafa de azeite fazem um par encantador. Ate-os com fio de cozinha."}},{"type":"products","slugs":["sardine-spoon-rest","ceramic-oil-bottle"]}]'::jsonb, 'Terra Collective', 3, '2026-09-24')
on conflict (slug) do update set title = excluded.title, excerpt = excluded.excerpt, cover = excluded.cover, category = excluded.category, blocks = excluded.blocks, reading_minutes = excluded.reading_minutes;

